//! Practical manual-place weather application, using only public APIs.
use crate::{*,serde_json::{json,Value}};
pub fn controller(input:Value)->Value{let mut s=input["state"].clone();if !s.is_object(){s=json!({"route":"place","latitude":"","longitude":"","label":"","revision":0,"status":"Choose a place manually; no GPS is read","weather":null});}let e=&input["event"];let a=e["action"].as_str().unwrap_or("");let v=&e["reply"]["value"];let mut req=Value::Null;let mut child_event=e.clone();
match a{"start"=>req=collections::get("weather_place","selected","place.loaded"),"place.loaded" if e["reply"]["ok"]==true=>{s["revision"]=v["revision"].clone();if v["data"].is_object(){for k in["latitude","longitude","label"]{s[k]=v["data"][k].clone();}}},"place.latitude"|"place.longitude"|"place.label"=>s[&a[6..]]=e["value"].clone(),"place.open"=>{let p=place(&s);match p{Ok(_)=>req=collections::transact("weather_place",s["revision"].as_u64().unwrap_or(0),1,None,vec![collections::put("selected",json!({"latitude":s["latitude"],"longitude":s["longitude"],"label":s["label"]}))],"place.saved"),Err(err)=>s["status"]=json!(err)}},"place.saved" if e["reply"]["ok"]==true=>{s["revision"]=v["revision"].clone();s["weather"]=Value::Null;s["route"]=json!("weather");child_event=json!({"action":"start"});},"place.back"=>s["route"]=json!("place"),_=>{}}
if a.starts_with("place.")&&e["reply"]["ok"]==false{s["status"]=json!("Place could not be loaded/saved. Previous selection retained.");}
if s["route"]=="weather"{if let Ok(p)=place(&s){let mut f=crate::weather::controller(json!({"state":s["weather"],"event":child_event}),&p);s["weather"]=f["state"].clone();f["state"]=s;f["back_action"]=json!("place.back");return f}}
Screen::new("Weather",s.clone()).body(vec![field("place.label","Place name",s["label"].as_str().unwrap_or("")),field("place.latitude","Latitude (-90 to90)",s["latitude"].as_str().unwrap_or("")),field("place.longitude","Longitude (-180 to180)",s["longitude"].as_str().unwrap_or("")),label("place.status",s["status"].as_str().unwrap_or("")),button("place.open","Open selected place")]).scrollable().effect(req).finish()}
fn place(s:&Value)->Result<crate::weather::Place,String>{let lat=s["latitude"].as_str().and_then(|v|v.trim().parse().ok()).ok_or("Enter a numeric latitude")?;let lon=s["longitude"].as_str().and_then(|v|v.trim().parse().ok()).ok_or("Enter a numeric longitude")?;crate::weather::Place::open_meteo(lat,lon,s["label"].as_str().unwrap_or(""))}
